import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.nextLine();
        String line = scanner.nextLine();

        StringBuilder output = new StringBuilder();
        int parenthesesWordCount = 0;
        int idx = 0;

        while (idx < line.length()) {
            if (line.charAt(idx) == '(') {
                output.append('_');
                idx++;
                StringBuilder insideParentheses = new StringBuilder();
                while (line.charAt(idx) != ')') {
                    insideParentheses.append(line.charAt(idx));
                    idx++;
                }
                String[] words = insideParentheses.toString().split("_");
                for (String w : words) {
                    if (!w.isEmpty()) {
                        parenthesesWordCount++;
                    }
                }
            } else {
                output.append(line.charAt(idx));
            }
            idx++;
        }

        String[] parts = output.toString().split("_");
        int maxWordLen = 0;
        for (String part : parts) {
            if (!part.isEmpty() && part.length() > maxWordLen) {
                maxWordLen = part.length();
            }
        }

        System.out.println(maxWordLen + " " + parenthesesWordCount);
        scanner.close();
    }
}
