#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the newline after the integer input
    std::string line;
    std::getline(std::cin, line);

    std::string output;
    int parenthesesWordCount = 0;
    size_t idx = 0;

    while (idx < line.length()) {
        if (line[idx] == '(') {
            output += '_';
            idx++;
            std::string insideParentheses;
            while (idx < line.length() && line[idx] != ')') {
                insideParentheses += line[idx];
                idx++;
            }
            // Skip the closing parenthesis
            if (idx < line.length() && line[idx] == ')') {
                idx++;
            }
            std::stringstream ss(insideParentheses);
            std::string word;
            while (std::getline(ss, word, '_')) {
                if (!word.empty()) {
                    parenthesesWordCount++;
                }
            }
        } else {
            output += line[idx];
            idx++;
        }
    }

    std::stringstream ss(output);
    std::string part;
    int maxWordLen = 0;
    while (ss >> part) {
        if (!part.empty() && part.length() > maxWordLen) {
            maxWordLen = part.length();
        }
    }

    std::cout << maxWordLen << " " << parenthesesWordCount << std::endl;
    return 0;
}
